import sqlite3
import sys

def get_employee(employee_id):
    conn = sqlite3.connect('/data/employees.db')
    cursor = conn.cursor()

    # Query the database for the employee
    query = f"SELECT id, name, email, salary, department FROM employees WHERE id = {employee_id}"
    cursor.execute(query)

    result = cursor.fetchone()
    conn.close()

    if result:
        return {
            'id': result[0],
            'name': result[1],
            'email': result[2],
            'salary': result[3],
            'department': result[4]
        }
    return None

if __name__ == '__main__':
    if len(sys.argv) > 1:
        emp_id = sys.argv[1]
        employee = get_employee(emp_id)
        if employee:
            print(f"Found: {employee['name']} ({employee['email']}) - {employee['department']}")
        else:
            print('Employee not found')
    else:
        print('Usage: python script.py <employee_id>')
